function plot_q5_procedure_roi_long45_allqc(phase_key)
if nargin<1,phase_key="procedure";end;root=fullfile(fileparts(fileparts(fileparts(mfilename('fullpath')))),'results',sprintf('q5_intrinsic_%s',phase_key),'cohort_specification');out=fullfile(root,'figures_long45_allQC');if ~isfolder(out),mkdir(out);end;I=readtable(fullfile(root,sprintf('q5_high_intrinsic_minus_low_intrinsic_%s_individual_ROI_long45_allQC_n30.csv',phase_key)),'TextType','string');G=readtable(fullfile(root,sprintf('q5_high_intrinsic_minus_low_intrinsic_%s_group_ROI_long45_allQC_n30.csv',phase_key)),'TextType','string');C=readtable(fullfile(root,sprintf('q5_high_intrinsic_minus_low_intrinsic_%s_group_channel_summary_n30.csv',phase_key)),'TextType','string');K=unique(I(I.hemoglobin=="HbO",{'roi','laterality'}),'rows','stable');
f=figure('Color','w','Position',[100 100 1800 1050]);tiledlayout(2,1);for h=1:2,hb=["HbO","HbR"];U=I(I.hemoglobin==hb(h),:);M=nan(30,height(K));for k=1:height(K),V=U(U.roi==K.roi(k)&U.laterality==K.laterality(k),:);M(:,k)=V.mean_contrast_beta;end;nexttile;z=max(abs(M(:)));imagesc(M,[-z z]);colormap(gca,bwr(256));cb=colorbar;cb.Color='k';set(gca,'XTick',1:height(K),'XTickLabel',strcat(K.roi," | ",K.laterality),'XTickLabelRotation',35,'YTick',1:30,'YTickLabel',compose('%03d',1:30),'XColor','k','YColor','k');xlabel('Broad ROI | laterality','Color','k');ylabel('Subject','Color','k');title(hb(h),'Color','k');end;sgtitle(sprintf('Q5 %s layer 1: individual ROI beta | high intrinsic - low intrinsic',upper(phase_key)),'Color','k');exportgraphics(f,fullfile(out,sprintf('q5_%s_layer1_individual_roi_heatmaps_long45_allQC.png',phase_key)),'Resolution',220);close(f);
f=figure('Color','w','Position',[100 100 1900 700]);tiledlayout(2,1);for h=1:2,hb=["HbO","HbR"];U=C(C.hemoglobin==hb(h)&C.channel_type=="Long",:);nexttile;v=U.mean_contrast_beta';z=max(abs(v));imagesc(v,[-z z]);colormap(gca,bwr(256));cb=colorbar;cb.Color='k';set(gca,'YTick',1,'YTickLabel',hb(h),'XTick',1:height(U),'XTickLabel',compose('ch%d',U.channel_index),'XTickLabelRotation',45,'XColor','k','YColor','k');xlabel('Long channel','Color','k');title('Group beta; black dot = p<.05','Color','k');hold on;plot(find(U.group_p_two_sided<.05),ones(sum(U.group_p_two_sided<.05),1),'ko','MarkerFaceColor','k');end;sgtitle(sprintf('Q5 %s layer 3: long-channel group effects',upper(phase_key)),'Color','k');exportgraphics(f,fullfile(out,sprintf('q5_%s_layer3_long_channel_effects_long45_allQC.png',phase_key)),'Resolution',220);close(f);
end
function c=bwr(n),h=floor(n/2);c=[[linspace(.1,1,h)' linspace(.3,1,h)' ones(h,1)];[ones(n-h,1) linspace(1,.15,n-h)' linspace(1,.15,n-h)']];end
